mapper.select:
select t1.*, (select t2.name from sys_dept t2 where t2.id=t1.dept_id) deptName
	from sys_dict_type t1 


		and t1.dict_type like #{dictType}


		and t1.dict_name like #{dictName}


		and t1.dept_id = #{deptId}


		and t1.dept_id in

			#{id}



order by t1.sort

select t1.*, (select t2.name from sys_dept t2 where t2.id=t1.dept_id) deptName
	from sys_dict_type t1 

	and t1.id = #{id}
